-- Guess Who, solo vs a bot. This build does NOT put your own face on the board. Characters are the 24 entries of
-- chars.txt: each is (hair, eyes, mouth) with 4 styles per slot, drawn with the Player face art (faces.bin/faces.idx,
-- words.txt). The six binary traits are the hi and lo bit of each slot. chars.txt was generated by a seeded search so
-- every trait splits the board 12/12 (crossplay docs/apps/guesswho.md, section 4).
--
-- Controls:
--   board: Up/Down/Left/Right move. Confirm folds or unfolds a tile (visual only).
--   bottom bar: Left/Right chooses ASK or GUESS. Confirm opens it. Up returns to the board.
--   ASK: Up/Down chooses one of six trait questions; Confirm asks (the bot answers for its secret). Back cancels.
--   GUESS: move onto a tile and Confirm to guess it. Right answer wins; a wrong guess loses. Back cancels.
-- The bot picks its secret once at the start and never changes it.

local W, H = 0, 0
local SLOTS = { "hair", "eyes", "mouth" }
local WORDS = {}
local idx = {}
local chars = {}   -- { {h, e, m}, ... } with values 0..3

local function clip(s, n) return #s > n and s:sub(1, n) or s end

local function load_data()
  local words = fs.read("app:words.txt") or ""
  for line in words:gmatch("[^\n]+") do
    local slot, rest = line:match("^(%S+) (.*)$")
    if slot then
      WORDS[slot] = {}
      for w in rest:gmatch("%S+") do WORDS[slot][#WORDS[slot] + 1] = w end
    end
  end
  local index = fs.read("app:faces.idx") or ""
  for line in index:gmatch("[^\n]+") do
    local key, w, h, off, len = line:match("^(%S+) (%d+) (%d+) (%d+) (%d+)$")
    if key then idx[key] = { w = tonumber(w), h = tonumber(h), off = tonumber(off), len = tonumber(len) } end
  end
  local ch = fs.read("app:chars.txt") or ""
  for a, b, c in ch:gmatch("(%d) (%d) (%d)") do chars[#chars + 1] = { tonumber(a), tonumber(b), tonumber(c) } end
end

local function draw_layer(key, x, y, size)
  local e = idx[key]
  if not e then return end
  local bits = fs.read("app:faces.bin", e.off, e.len)
  if not bits then return end
  local rb = (e.w + 7) // 8
  for r = 0, e.h - 1 do
    local row = r * rb
    for c = 0, e.w - 1 do
      local byte = bits:byte(row + c // 8 + 1)
      if ((byte >> (7 - c % 8)) & 1) == 0 then gfx.pixel(x + c, y + r, true) end
    end
  end
end

-- face at (x,y), drawn at 48 px, from a value triple (indices 0..3 map to WORDS[slot][1..4])
local function draw_face(x, y, v)
  draw_layer("base_48", x, y)
  for s, slot in ipairs(SLOTS) do
    local word = WORDS[slot] and WORDS[slot][v[s] + 1]
    if word then draw_layer(slot .. "_" .. word .. "_48", x, y) end
  end
end

-- the six trait questions: each is { text, test(c) -> bool }
local function bit(v, hi) if hi then return v >> 1 end return v & 1 end
local QUESTIONS = {}
for s, slot in ipairs(SLOTS) do
  QUESTIONS[#QUESTIONS + 1] = { slot = slot, s = s, hi = true }
  QUESTIONS[#QUESTIONS + 1] = { slot = slot, s = s, hi = false }
end
local function question_text(q)
  local w = WORDS[q.slot] or {}
  if q.hi then return string.format("%s is %s or %s?", q.slot:upper(), w[3] or "?", w[4] or "?")
  else return string.format("%s is %s or %s?", q.slot:upper(), w[2] or "?", w[4] or "?") end
end
local function answer_yes(q, c) return bit(c[q.s], q.hi) == 1 end

local function tile_xy(i)
  local col = (i - 1) % 4
  local row = (i - 1) // 4
  return 30 + col * 110, 60 + row * 66
end

local function draw(state)
  gfx.clear(); W, H = gfx.size()
  gfx.rect(0, 0, W, 40, true); gfx.text(14, 10, "Guess Who", "ui12", "bw")
  for i = 1, 24 do
    local x, y = tile_xy(i)
    local c = chars[i]
    if state.folded[i] then gfx.rect(x, y, 56, 56, false); gfx.text(x + 12, y + 16, "x", "ui12")
    else draw_face(x + 4, y + 4, c) end
    if state.cur.kind == "tile" and state.cur.i == i then gfx.rect(x - 2, y - 2, 60, 60, false) end
  end
  -- bottom bar
  local by = 60 + 6 * 66 + 10
  local ask_sel = state.cur.kind == "bar" and state.cur.i == 1
  local guess_sel = state.cur.kind == "bar" and state.cur.i == 2
  gfx.text(30, by, ask_sel and "[ ASK ]" or "  ASK  ", "ui12", ask_sel and "b" or nil)
  gfx.text(260, by, guess_sel and "[ GUESS ]" or "  GUESS  ", "ui12", guess_sel and "b" or nil)
  if state.mode == "ask" then
    gfx.rect(10, by + 30, W - 20, 6 * 26 + 30, false)
    for i, q in ipairs(QUESTIONS) do
      local label = question_text(q)
      if i == state.qsel then gfx.rect(16, by + 34 + (i - 1) * 26, W - 32, 24, true); gfx.text(22, by + 36 + (i - 1) * 26, label, "small", "w")
      else gfx.text(22, by + 36 + (i - 1) * 26, label, "small") end
    end
  end
  local foot = state.msg or ""
  gfx.text(14, H - 60, clip(foot, 60), "ui12")
  gfx.text(14, H - 34, state.hint or "", "small")
  gfx.present()
end

local ok, err = pcall(function()
  W, H = gfx.size()
  load_data()
  if #chars ~= 24 or not WORDS.hair then
    gfx.clear(); gfx.text(14, 80, "Missing chars.txt or art files.", "ui12"); gfx.present()
    while input.wait() ~= "back" do end
    return
  end
  local ok2, b = pcall(crypto.random, 1)
  local secret = (ok2 and type(b) == "string" and #b == 1) and (b:byte() % 24 + 1) or math.random(24)
  local st = {
    cur = { kind = "tile", i = 1 },
    folded = {}, mode = "normal", qsel = 1, asked = 0,
    msg = "Bot has a secret. Ask a question or guess.",
    hint = "Confirm folds a tile. ASK/GUESS on the bottom row.",
  }
  local done = false
  local function move(dir)
    local cur = st.cur
    if cur.kind == "tile" then
      local row, col = (cur.i - 1) // 4 + 1, (cur.i - 1) % 4 + 1
      if dir == "up" then if row > 1 then cur.i = cur.i - 4 end
      elseif dir == "down" then
        if row < 6 then cur.i = cur.i + 4
        elseif st.mode == "normal" then cur = { kind = "bar", i = 1 } end
      elseif dir == "left" then cur.i = (col > 1) and cur.i - 1 or cur.i + 3
      elseif dir == "right" then cur.i = (col < 4) and cur.i + 1 or cur.i - 3 end
    elseif cur.kind == "bar" then
      if dir == "left" or dir == "right" then cur.i = 3 - cur.i
      elseif dir == "up" then cur = { kind = "tile", i = 21 } end
    end
    st.cur = cur
  end
  draw(st)
  while true do
    local e = input.wait()
    if e == "back" then
      if st.mode ~= "normal" then st.mode = "normal"; st.msg = ""
      else break end
    elseif not done then   -- once the result is shown, only back does anything
      if st.mode == "ask" then
      if e == "up" then st.qsel = st.qsel > 1 and st.qsel - 1 or #QUESTIONS
      elseif e == "down" then st.qsel = st.qsel < #QUESTIONS and st.qsel + 1 or 1
      elseif e == "confirm" then
        local q = QUESTIONS[st.qsel]
        st.asked = st.asked + 1
        st.msg = question_text(q) .. "  " .. (answer_yes(q, chars[secret]) and "YES" or "NO") .. "  (" .. st.asked .. " asked)"
        st.mode = "normal"
      end
    elseif st.mode == "guess" then
      if e == "confirm" and st.cur.kind == "tile" then
        if st.cur.i == secret then st.msg = "Correct. You win in " .. (st.asked + 1) .. " questions."
        else st.msg = "Wrong. The bot wins." end
        done = true
        st.mode = "normal"
      elseif e == "up" or e == "down" or e == "left" or e == "right" then move(e) end
    else
      if e == "up" or e == "down" or e == "left" or e == "right" then move(e)
      elseif e == "confirm" then
        if st.cur.kind == "tile" then
          st.folded[st.cur.i] = not st.folded[st.cur.i] or nil
        elseif st.cur.i == 1 then
          st.mode = "ask"; st.qsel = 1; st.msg = ""
        else
          st.mode = "guess"; st.msg = "Pick a tile and confirm to guess. Back cancels."
          st.cur = { kind = "tile", i = 1 }
        end
      end
      end
    end
    draw(st)
  end
end)
if not ok then
  gfx.clear(); gfx.text(10, 10, "err: " .. tostring(err):sub(1, 60), "ui12", "b"); gfx.present()
  while input.wait() ~= "back" do end
end
app.exit()
